  useEffect(()=>{if(!accountId&&accounts.length)setAccountId(accounts[0].id);},[JSON.stringify(accounts)]);
  useEffect(()=>{if(!account){setDetails(null);return;}let live=true;api('/accounts/'+accountId).then(v=>{if(live)setDetails(v);}).catch(e=>{if(live){setDetails(null);setError(e.message);}});return()=>{live=false;};},[accountId,account?.balance,p.revision]);
  useEffect(()=>{if(reviewing)setView('Fechamento de caixa');},[reviewing]);
