    {view==='Contas abertas'&&<div className="cash-columns"><section className="panel"><h2>Contas abertas</h2><label>Selecionar mesa<select value={accountId} onChange={e=>{setAccountId(e.target.value);p.setAccount(e.target.value);}}><option value="">Selecione uma mesa…</option>{accountOptions.map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></label>{!accounts.length&&<Empty>Nenhuma conta aberta no momento.</Empty>}{account&&<><h3>Consumo da mesa</h3><DataTable rows={(details?.items||[]).filter((i:Row)=>i.status!=='CANCELADO')} columns={[["description_snapshot","Produto"],["attendant_name","Atendente"],["quantity","Quantidade",v=>qty(v)],["line_total","Valor",v=>money(v)]]}/><div className="total-line">Total <b>{money(account.total)}</b></div>{p.can('account.adjust')&&<div className="two-buttons"><button className="secondary" disabled={p.disabled} onClick={()=>setDialog('desconto')}>Aplicar desconto</button><button className="secondary" disabled={p.disabled} onClick={()=>setDialog('acréscimo')}>Adicionar acréscimo</button></div>}<div className="balance-line">Falta receber: <b>{money(account.balance)}</b></div></>}</section><PaymentPanel p={p} account={account} details={details} open={open} reviewing={reviewing} session={session} onReceipt={setReceipt}/></div>}
